package dev.pixel.calculator.agent;
import android.content.*;import android.content.pm.PackageManager;import android.database.Cursor;import android.net.Uri;import android.os.*;import org.json.*;import java.util.concurrent.*;
/** Agent access is limited to apps signed with our existing application identity. */
public final class AgentProvider extends ContentProvider {
 public boolean onCreate(){return true;}
 @Override public Bundle call(String method,String arg,Bundle extras){
  if(getContext().getPackageManager().checkSignatures(android.os.Process.myUid(),Binder.getCallingUid())!=PackageManager.SIGNATURE_MATCH)throw new SecurityException("Caller signing identity does not match");
  Callable<Bundle> job=()->{long start=SystemClock.elapsedRealtime();JSONObject result;
   try{
    if(method.equals("capabilities"))result=new JSONObject().put("status","ok").put("schemaVersion",1).put("operations",new JSONArray().put("get_state").put("evaluate").put("continue").put("history_list").put("history_recall")).put("evaluate",new JSONObject().put("expression","Required string: numbers, decimals, negative operands, + - * /, postfix %. Uses the same precedence and contextual percentage rules as the keypad. No parentheses or scientific functions.").put("equalsCount","Optional integer 1..10, defaults to 1. Total equals presses, including the first result. Each extra press repeats the final operation.")).put("continue","params: {suffix: string starting with + - * /, equalsCount?: integer}. Apply an operation to the current displayed value using the same calculator engine.").put("history_list","Returns entries with index, expression and answer, newest first.").put("history_recall","params: {index: integer}. Reuse that saved answer as the current display, exactly like tapping the history row.").put("behavior","Replaces the current expression; updates the visible calculator and calculation history. Returns actual stored entry, error flag and revision.");
    else{CalculatorSession s=CalculatorSession.get(getContext());if(method.equals("get_state"))result=s.state();else if(method.equals("history_list")){JSONArray list=new JSONArray();for(int i=0;i<s.history.length();i++){JSONObject h=s.history.getJSONObject(i);list.put(new JSONObject().put("index",i).put("expression",h.getString("expression")).put("answer",h.getString("answer")));}result=new JSONObject().put("status","ok").put("entries",list);}else if(method.equals("history_recall")){JSONObject q=new JSONObject(extras.getString("params","{}"));Object raw=q.get("index");if(!(raw instanceof Number)||((Number)raw).doubleValue()!=((Number)raw).intValue())throw new IllegalArgumentException("index must be an integer");int index=q.getInt("index");if(index<0||index>=s.history.length())throw new IllegalArgumentException("Unknown history index");s.calc.recall(s.history.getJSONObject(index).getString("answer"));s.save();result=s.state().put("status","verified");if(MainActivity.instance!=null)MainActivity.instance.refreshFromSession();}else if(method.equals("evaluate")||method.equals("continue")){JSONObject q=new JSONObject(extras==null?"{}":extras.getString("params","{}"));Object count=q.opt("equalsCount");if(count!=null&&(!(count instanceof Number)||((Number)count).doubleValue()!=((Number)count).intValue()))throw new IllegalArgumentException("equalsCount must be an integer");String expression;if(method.equals("continue")){String suffix=q.getString("suffix");if(!suffix.matches("^[+*/−×÷-].+"))throw new IllegalArgumentException("suffix must start with an operator");if(s.calc.error)throw new IllegalArgumentException("Current display is an error");expression=s.calc.entry+suffix;}else expression=q.getString("expression");result=s.evaluate(expression,q.optInt("equalsCount",1));if(MainActivity.instance!=null)MainActivity.instance.refreshFromSession();}else throw new IllegalArgumentException("Unknown operation");}
   }catch(Exception e){result=new JSONObject().put("status","error").put("reason",e.getMessage());}
   if(method.equals("capabilities")){try(java.io.InputStream in=getContext().getAssets().open("agent-tools.json")){java.io.ByteArrayOutputStream bytes=new java.io.ByteArrayOutputStream();byte[] buf=new byte[4096];int n;while((n=in.read(buf))>0)bytes.write(buf,0,n);result.put("tools",new JSONArray(bytes.toString("UTF-8")));}}
   result.put("appElapsedMs",SystemClock.elapsedRealtime()-start);Bundle b=new Bundle();b.putString("result",result.toString());return b;
  };
  try{if(Looper.myLooper()==Looper.getMainLooper())return job.call();FutureTask<Bundle> task=new FutureTask<>(job);new Handler(Looper.getMainLooper()).post(task);return task.get(5,TimeUnit.SECONDS);}catch(Exception e){throw new IllegalStateException("Calculator command failed",e);}
 }
 public Cursor query(Uri u,String[] p,String s,String[] a,String o){throw new UnsupportedOperationException();}public String getType(Uri u){return null;}public Uri insert(Uri u,ContentValues v){throw new UnsupportedOperationException();}public int delete(Uri u,String s,String[] a){throw new UnsupportedOperationException();}public int update(Uri u,ContentValues v,String s,String[] a){throw new UnsupportedOperationException();}
}
